<?php
namespace App\Http\Requests;use Illuminate\Foundation\Http\FormRequest;class StoreEmployerJobRequest extends FormRequest{public function authorize():bool{return in_array($this->user()?->role,['employer','admin'],true);}public function rules():array{return ['title'=>'required|string|max:255','description'=>'required|string|min:50','location'=>'required|string|max:255','country'=>'required|string|max:100','job_type'=>'required|in:Full Time,Part Time,Contract,Internship,Temporary','work_mode'=>'required|in:Office,Hybrid,Remote','experience_min'=>'nullable|integer|min:0|max:60','experience_max'=>'nullable|integer|gte:experience_min|max:60','salary_min'=>'nullable|numeric|min:0','salary_max'=>'nullable|numeric|gte:salary_min','education'=>'nullable|string|max:255','vacancies'=>'required|integer|min:1|max:10000','skills'=>'nullable|string|max:1000','is_confidential'=>'nullable|boolean','action'=>'required|in:draft,submit'];}}
